class Solution {
public:
    struct TrieNode {
        TrieNode* left = 0, * right = 0;
    };

    void addNode(TrieNode* head, int st)
    {
        bitset<32> p = bitset<32>(st);
        for (int i = 31; i >= 0; i--)
        {
            if (p.test(i))
            {
                if (!head->right)
                    head->right = new TrieNode();
                head = head->right;
            }
            else
            {
                if (!head->left)
                    head->left = new TrieNode();
                head = head->left;
            }
        }
    }

    int getMax(TrieNode* head, int st)
    {
        if (!head)
            return -1;
        bitset<32> p = bitset<32>(st);

        int ans = 0;

        for (int i = 31; i >= 0; i--)
        {
            if (!head->right && !head->left)
                return -1;
            ans *= 2;

            if (p.test(i))
            {
                if (head->left)
                    head = head->left;
                else
                {
                    head = head->right;
                    ans++;
                }
            }
            else   
            {
                if (head->right)
                {
                    head = head->right;
                    ans++;
                }
                else
                    head = head->left;
            }
        }

        return ans;
    }

    vector<int> maximizeXor(vector<int>& nums, vector<vector<int>>& que) {
        sort(nums.begin(), nums.end());
        for (int  i = 0; i < que.size(); i++)
        {
            reverse(que[i].begin(), que[i].end());
            que[i].push_back(i);
        }
        vector<int> ans(que.size());

        sort(que.begin(), que.end());

        TrieNode* head = new TrieNode();

        int ind = 0;

        for (auto e : que)
        {
            while (nums[ind] <= e[0] && ind < nums.size())
            {
                addNode(head, nums[ind]);
                ind++;
            }

            ans[e[2]] = getMax(head, e[1]);
            if (ans[e[2]] != -1)
                ans[e[2]] ^= e[1];
        }

        return ans;
    }
};
